    0: (* 初始化 *)
        {p}State := 10;
    10: (* 执行步骤 *)
        {p}State := 20;
    20: (* 完成 *)
        {p}State := 0;
ELSE
    {p}State := 0;
END_CASE;

FOR {p}Index := 1 TO 10 DO
    (* 循环程序段 *)
END_FOR;

